import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as e,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux 文件系统类型导览 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 文件系统类型导览 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 文件系统类型导览 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 文件系统类型导览 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190820 A guided tour of Linux file system types","title":"Linux 文件系统类型导览","tag":"201908","desc":""},"relativePath":"201908/20190820 A guided tour of Linux file system types.md","filePath":"[post].md"}'),u={name:"201908/20190820 A guided tour of Linux file system types.md"};function f(c,s,m,h,g,x){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="linux-文件系统类型导览" tabindex="-1">Linux 文件系统类型导览 <a class="header-anchor" href="#linux-文件系统类型导览" aria-label="Permalink to “Linux 文件系统类型导览”">​</a></h1><blockquote><p>Linux 文件系统多年来在不断发展，让我们来看一下文件系统类型。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/27/175516vzrp4j4zevcqr66c.jpg" alt=""></p><p>虽然对于普通用户来说可能并不明显，但在过去十年左右的时间里，Linux 文件系统已经发生了显著的变化，这使它们能够更好对抗损坏和性能问题。</p><p>如今大多数 Linux 系统使用名为 ext4 的文件系统。 “ext” 代表“<ruby>扩展<rt>extended</rt></ruby>”，“4” 表示这是此文件系统的第 4 代。随着时间的推移添加的功能包括：能够提供越来越大的文件系统（目前大到 1,000,000 TiB）和更大的文件（高达 16 TiB），更抗系统崩溃，更少碎片（将单个文件分散为存在多个位置的块）以提高性能。</p><p>ext4 文件系统还带来了对性能、可伸缩性和容量的其他改进。实现了元数据和日志校验和以增强可靠性。时间戳现在可以跟踪纳秒级变化，以便更好地对文件打戳（例如，文件创建和最后更新时间）。并且，在时间戳字段中增加了两个位，2038 年的问题（存储日期/时间的字段将从最大值翻转到零）已被推迟到了 400 多年之后（到 2446）。</p><h3 id="文件系统类型" tabindex="-1">文件系统类型 <a class="header-anchor" href="#文件系统类型" aria-label="Permalink to “文件系统类型”">​</a></h3><p>要确定 Linux 系统上文件系统的类型，请使用 <code>df</code> 命令。下面显示的命令中的 <code>-T</code> 选项显示文件系统类型。 <code>-h</code> 显示“易读的”磁盘大小。换句话说，调整报告的单位（如 M 和 G），使人们更好地理解。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | head -10</span></span>
<span class="line"><span>Filesystem     Type      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>udev           devtmpfs  2.9G     0  2.9G   0% /dev</span></span>
<span class="line"><span>tmpfs          tmpfs     596M  1.5M  595M   1% /run</span></span>
<span class="line"><span>/dev/sda1      ext4      110G   50G   55G  48% /</span></span>
<span class="line"><span>/dev/sdb2      ext4      457G  642M  434G   1% /apps</span></span>
<span class="line"><span>tmpfs          tmpfs     3.0G     0  3.0G   0% /dev/shm</span></span>
<span class="line"><span>tmpfs          tmpfs     5.0M  4.0K  5.0M   1% /run/lock</span></span>
<span class="line"><span>tmpfs          tmpfs     3.0G     0  3.0G   0% /sys/fs/cgroup</span></span>
<span class="line"><span>/dev/loop0     squashfs   89M   89M     0 100% /snap/core/7270</span></span>
<span class="line"><span>/dev/loop2     squashfs  142M  142M     0 100% /snap/hexchat/42</span></span></code></pre></div><p>请注意，<code>/</code>（根）和 <code>/apps</code> 的文件系统都是 ext4，而 <code>/dev</code> 是 devtmpfs 文件系统（一个由内核填充的自动化设备节点）。其他的文件系统显示为 tmpfs（驻留在内存和/或交换分区中的临时文件系统）和 squashfs（只读压缩文件系统的文件系统，用于快照包）。</p><p>还有 proc 文件系统，用于存储正在运行的进程的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -T /proc</span></span>
<span class="line"><span>Filesystem     Type 1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>proc           proc         0     0         0    - /proc</span></span></code></pre></div><p>当你在整个文件系统中游览时，可能会遇到许多其他文件系统类型。例如，当你移动到目录中并想了解它的文件系统时，可以运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /dev/mqueue; df -T .</span></span>
<span class="line"><span>Filesystem     Type   1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>mqueue         mqueue         0     0         0    - /dev/mqueue</span></span>
<span class="line"><span>$ cd /sys; df -T .</span></span>
<span class="line"><span>Filesystem     Type  1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>sysfs          sysfs         0     0         0    - /sys</span></span>
<span class="line"><span>$ cd /sys/kernel/security; df -T .</span></span>
<span class="line"><span>Filesystem     Type       1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>securityfs     securityfs         0     0         0    - /sys/kernel/security</span></span></code></pre></div><p>与其他 Linux 命令一样，这里的 <code>.</code> 代表整个文件系统的当前位置。</p><p>这些和其他独特的文件系统提供了一些特殊功能。例如，securityfs 提供支持安全模块的文件系统。</p><p>Linux 文件系统需要能够抵抗损坏，能够承受系统崩溃并提供快速、可靠的性能。由几代 ext 文件系统和新一代专用文件系统提供的改进使 Linux 系统更易于管理和更可靠。</p><hr>`,18)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3432990/a-guided-tour-of-linux-file-system-types.html"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3432990/a-guided-tour-of-linux-file-system-types.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const T=i(u,[["render",f]]);export{b as __pageData,T as default};
